/bin/bash -lc "python3 - <<'PY'
import ast,json,hashlib
from pathlib import Path
p=json.loads(Path('proposal.json').read_text()); r=json.loads(Path('runtime.json').read_text())
def validate(value,schema,path='study'):
 t=schema.get('type')
 ok={'object':lambda:isinstance(value,dict),'array':lambda:isinstance(value,list),'string':lambda:isinstance(value,str)}
 if t: assert ok[t](),(path,t,type(value))
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  if 'items' in schema:
   for i,v in enumerate(value): validate(v,schema['items'],f'{path}[{i}]')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'missing fields')
  properties=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=set(properties),(path,'unknown fields')
  for k,v in value.items():
   if k in properties: validate(v,properties[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert set(p)=={'study','parent_trial','variants'}
assert r['phase']=='propose' and r['context']['previous_runtime_error'] is None
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in allowed and set(p['study']['evidence_refs'])<=allowed
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
parent_tree=ast.parse(Path('history_r0002_support_pair.py').read_text())
parent_cls=next(x for x in parent_tree.body if isinstance(x,ast.ClassDef))
parent_methods={x.name:x for x in parent_cls.body if isinstance(x,ast.FunctionDef)}
normalized=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert v['role'] in ['candidate','control']
 source=Path(v['file']).read_text(); tree=ast.parse(source,filename=v['file'])
 config_node=next(x for x in tree.body if isinstance(x,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in x.targets))
 assert ast.literal_eval(config_node.value)==v['config']
 imports=[]
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): imports.extend(x.name.split('.')[0] for x in node.names)
  if isinstance(node,ast.ImportFrom): imports.append(node.module.split('.')[0])
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name): assert node.func.id not in ['open','exec','eval','__import__','compile','input']
 assert set(imports)=={'math','torch'},imports
 cls=next(x for x in tree.body if isinstance(x,ast.ClassDef) and x.name=='Model')
 methods={x.name:x for x in cls.body if isinstance(x,ast.FunctionDef)}
 for name in ['_statistics','_evidence_from_statistics','_pair_statistics','_pair_evidence']:
  assert ast.dump(methods[name],include_attributes=False)==ast.dump(parent_methods[name],include_attributes=False),(v['file'],name)
 assert {'__init__','forward','diagnostics','_history_views','_selected_summary'}<=set(methods)
 assert 'training_loss' not in methods
 for k in ['kind','embedding_dim','hidden','lr','statistic_target','statistic_scale','temporal_statistic','half_life_seconds','pair_statistic']:
  assert v['config'][k]==json.loads(Path('workspace.json').read_text())['initial_model_config'][k]
 config_node.value=ast.Dict(keys=[],values=[])
 normalized.append(ast.dump(tree,include_attributes=False))
 print(v['file'],'AST/import/config checks passed; four inherited statistic methods identical; sha256',hashlib.sha256(source.encode()).hexdigest())
assert len(set(normalized))==1,'variant differences beyond CONFIG'
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert {(v['config']['summary_grouping'],v['config']['summary_weighting']) for v in p['variants']}=={(a,b) for a in ['action','global'] for b in ['attention','mean']}
print('Study validated against every schema keyword present; four-cell factorial complete; no local training executed.')
print('Expected parameters',17133347+4*16*128,'dense',54659+4*16*128,'embedding',17078688)
